import json
import unittest
import os
import sys
import tempfile
from pathlib import Path
from copy import deepcopy
from check_browser_renderer_evidence import validate, PACKAGE, TEST, MARKER, strict_json, descriptor, INPUTS, digest, read_file


class BrowserEvidenceTests(unittest.TestCase):
    def test_requires_actual_browser_and_complete_package(self):
        events = [{"Package": PACKAGE, "Action": "run", "Test": TEST},
                  {"Package": PACKAGE, "Action": "output", "Test": TEST, "Output": MARKER + "\n"},
                  {"Package": PACKAGE, "Action": "pass", "Test": TEST},
                  {"Package": PACKAGE, "Action": "pass"}]
        encode = lambda values: "\n".join(json.dumps(v) for v in values).encode()
        validate(encode(events))
        for values in ([e for i, e in enumerate(events) if i != j] for j in range(4)):
            with self.assertRaises(ValueError): validate(encode(values))
        for action in ("skip", "fail"):
            with self.assertRaises(ValueError): validate(encode([*events, {"Package": PACKAGE, "Action": action}]))
        for values in ([events[-1]], events + events, list(reversed(events)),
                       [{**e, "Package": "unrelated"} for e in events]):
            with self.assertRaises(ValueError): validate(encode(values))

    def test_closed_json_and_cached_output(self):
        for raw in ('{"a":1,"a":2}', '{"a":NaN}', '{"a":Infinity}'):
            with self.assertRaises(ValueError): strict_json(raw)
        with self.assertRaises(ValueError):
            validate(json.dumps({"Package": PACKAGE, "Action": "output", "Output": "ok (cached)"}).encode())

    def test_independent_module_source_and_run_binding(self):
        module = b"\0asm\1\0\0\0"
        identity = {"source": "a" * 40, "tree": "b" * 40, "run": "123", "attempt": "2"}
        hashes = {name: "c" * 64 for name in INPUTS}
        value = {"format": "kanz-browser-render-asset-v1", "abi": 1, **identity,
                 "sourceKind": "committed-ci", "sources": hashes, "moduleSHA256": digest(module),
                 "moduleBytes": len(module), "maxMemoryBytes": 2097152}
        def entry(v):
            return ("// Generated by the shared pinned recipe.\nimport url from './browser-render." + digest(module)
                    + ".wasm?url&no-inline'\nexport const rendererAsset = " + json.dumps(v)
                    + " as const\nexport { url }\n").encode()
        descriptor(entry(value), module, identity, hashes)
        for key, replacement in (("source", "d"*40), ("tree", "d"*40), ("run", "122"),
                                 ("attempt", "1"), ("sourceKind", "local-build"), ("moduleBytes", True),
                                 ("moduleSHA256", "d"*64), ("sources", {}), ("abi", True)):
            changed = deepcopy(value); changed[key] = replacement
            with self.assertRaises(ValueError): descriptor(entry(changed), module, identity, hashes)
        with self.assertRaises(ValueError): descriptor(entry(value), module + b"x", identity, hashes)
        with self.assertRaises(ValueError): descriptor(entry(value).replace(b'"abi": 1', b'"abi": 1, "abi": 1'), module, identity, hashes)

    @unittest.skipUnless(sys.platform == "linux", "actual no-follow/nonblocking reader requires Linux")
    def test_real_bounded_reader(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "proof"
            path.write_bytes(b"abc")
            self.assertEqual(read_file(path, 3), b"abc")
            with self.assertRaises(ValueError): read_file(path, 2)
            link = Path(directory) / "link"; link.symlink_to(path)
            with self.assertRaises(OSError): read_file(link, 3)
            fifo = Path(directory) / "fifo"; os.mkfifo(fifo)
            with self.assertRaises(ValueError): read_file(fifo, 3)
            hard = Path(directory) / "hard"; os.link(path, hard)
            with self.assertRaises(ValueError): read_file(hard, 3)


if __name__ == "__main__": unittest.main()
